public static int sumStack(Stack<Integer> s) {
    Stack<Integer> temp = new Stack<Integer>();
    int sum = 0;
    while (!s.isEmpty()) {
        int x = s.pop();
        sum = sum + x;
        temp.push(x);
    }
    // מחזירים את האיברים — המחסנית חוזרת להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
    return sum;
}

public static int sizeOf(Stack<Integer> s) {
    Stack<Integer> temp = new Stack<Integer>();
    int count = 0;
    while (!s.isEmpty()) {
        temp.push(s.pop());
        count++;
    }
    // מחזירים את האיברים — המחסנית חוזרת להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
    return count;
}

